{"path": "src/components/ResponsiveNav.tsx", "mode": "create", "overwrite": true, "content": "import { useEffect, useState } from 'react';

const NAV_LINKS = [
  { href: '#board', label: 'Board' },
  { href: '#activity', label: 'Activity' },
  { href: '#reports', label: 'Reports' },
];

const getHash = () => (typeof window === 'undefined' ? '' : window.location.hash);

export function ResponsiveNav() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(getHash);

  useEffect(() => {
    const sync = () => setActive(getHash());
    sync();
    window.addEventListener('hashchange', sync);
    return () => window.removeEventListener('hashchange', sync);
  }, []);

  return (
    <nav className="top-nav" aria-label="Primary navigation">
      <a className="brand" href="#top">RB</a>
      <button
        className="menu-button"
        type="button"
        aria-expanded={open}
        aria-controls="nav-links"
        onClick={() => setOpen((value) => !value)}
      >
        Menu
      </button>
      <div id="nav-links" className={`nav-links ${open ? 'open' : ''}`}>
        {NAV_LINKS.map((link) => (
          <a
            key={link.href}
            href={link.href}
            aria-current={active === link.href ? 'page' : undefined}
            onClick={() => {
              setActive(link.href);
              setOpen(false);
            }}
          >
            {link.label}
          </a>
        ))}
      </div>
    </nav>
  );
}
"}

